# KN7000 "Program" flash image, build 935 (firmware v1.5) - byte-exact.
# Panasonic MN10300, mapped at CPU 0x48400000. GENERATED by
# `tools/gen_program_s.py --profile b935` (make program-src-935) -- do not
# edit by hand.
#
# Build 935 is the release before 941. tools/offset_map.py aligns the two:
# all 2302 reflection-named functions sit at the address the map gives
# (most of code region 1 at -66 bytes, the library image at -100); the
# difference is concentrated in the DSP boot and record-interpreter code at
# the front of code region 1 (941 rewrote and reordered it) and in moved
# blocks of the data region. Names, the function split, FUNC_END caps,
# data islands, library ranges and notes are ported from build 941 where
# the map places them 1:1 (kn7000_b935*.sym); routines the map cannot
# place take a 941 name only where tools/port_names_by_code.py finds the
# same code (kn7000_b935_bycode.sym). CPU addresses quoted in the notes
# are translated to build 935; "build-941 0x..." marks one that has no
# counterpart. make verify-935 guarantees byte-identity.
#
# Labels in converted code: a function keeps its symbol-file name (an
# `X_entry` label is the register-save `call` entry a few bytes after the
# `movm` / `add -N, sp` prologue of X); func_<ADDR> is a function no symbol
# file names yet (a call target, a pointer to a prologue, or the code after a
# FUNC_END cap), its call entry func_<ADDR>_entry; loc_<ADDR> a branch
# target or code address inside a function, rodata_<ADDR> typed data. A
# symbol-file name that sits on the call entry itself keeps that address: its
# block header then says where the unlabelled prologue in front of it starts.

.equ PROGRAM_ROM_BASE, 0x48400000
.mnbase 0x48400000   # CPU address of output offset 0 (for PC-relative ops)
.include "src/b935/symbols.inc"
.include "src/b935/program/data/gui_event_ids.inc"   # EV_ / MT_ ids, named in mov / cmp immediates
.include "src/b935/program/data/gui_code_ids.inc"   # TT_ / MD_ / CLASS_ / FN_ / object ids, likewise

# 2 names converted code references outside itself (not in symbols.inc)
.equ TableRomDirectory, 0x48000000
.equ LibRomImageBase, 0x487B8F6D

# 1 branch targets outside the converted code
.equ loc_48535550, 0x48535550

# 11 data addresses named by annotations/*.ann
.equ DrawIcons_PixelPairTable, 0x485A2278   # 256 x u16: icon byte -> {left, right} palette index (nibble n -> n, or 0xF0+n if n >= 8)
.equ Pixel4bppPairTable, 0x485A2478   # u16[256]: byte -> two pixels {lo: 0x20 + high nibble, hi: 0x20 + low nibble}
.equ BmpSignature, 0x485A2878   # "BM", NUL-terminated: the BMP bfType GetBitmapInfo compares
.equ RoundCornerPixels, 0x485A287C   # 8 x {u16 dx, u16 dy}: the pixels a DrawJpegFileR corner keeps
.equ SjisMissingGlyph, 0x485A289C   # 16x16 1 bpp column-major glyph: a box with an X in it
.equ DrawEnable, 0x5002A01C   # nonzero: drawing allowed (tested before every DrawXxx_Impl)
.equ FrameBuffer, 0x500D4080   # 640 x 240 x 8 bpp, stride 0x280
.equ BitmapTablePtr, 0x50122DAC   # -> bitmap descriptors {s16 w, s16 h, u8 *pixels}
.equ FrameTablePtr, 0x50122DB0   # -> frame-piece descriptors {s16 w, s16 h, u8 *pixels}
.equ IconTablePtr, 0x50122DB4   # -> icon descriptors {s16 w, s16 h, u8 *pixels}
.equ FontTablePtr, 0x50122DB8   # -> 0x14-byte font descriptors

# ---- boot header (0x0..0x80) ----
_reset:
    jmp     ResetEntry
    nop
    nop
    nop
    nop
    nop
_vector_08:
    jmp     func_484D778D
    .space 2, 0xFF
_rom_marker:
    .byte 0x15                              # firmware release v1.5 (shown by the boot ROM as NOW(CURRENT))
    .space 0x80 - 0x10, 0xFF
    .org 0x000080

