.include "src/b935/program/region1_0A.s"
.include "src/b935/program/region1_0B.s"
.include "src/b935/program/region1_0C.s"
.include "src/b935/program/tail_code.s"

# ---- code region 2 (MILK MN10300 kernel + zlib 1.0.4). The library
#      image the boot self-loads to 0x4C000000 starts at file offset
#      0x3B8F6D (notes/library-rom-loading.md); converted lib functions
#      are assembled under the shifted .mnbase so their labels and
#      PC-relative encodings are the 0x4C link addresses. ----
.mnbase 0x4BC47093   # lib window: CPU 0x4C000000 = file 0x3B8F6D
.include "src/b935/program/library_00.s"
.include "src/b935/program/library_01.s"
.mnbase 0x48400000

.org 0x3F6E9D   # end of image

# ---- erased flash (0xFF) to the end of the device ----
.space 0x400000 - 0x3F6E9D, 0xFF
.org 0x400000
